script:
frappe.ui.form.on('Patient', {
    refresh: (frm) => {
        // Play a sound effect (e.g., ping.mp3)
        frappe.utils.play_sound("ping")
        audio.play().catch(err => {
            console.warn('Audio playback failed:', err);
        });

        // Show a message
        frappe.msgprint({
            title: 'Patient Form Refreshed',
            message: 'A sound has been played.',
            indicator: 'blue'
        });
    }
});

frappe.ui.form.on('User', {
    refresh(frm) {
        frm.add_custom_button('Send Welcome Email', () => {
            frappe.msgprint('Email Sent!');
        }, 'Actions');
    }
});
